CREATE TYPE "ChallanStatus" AS ENUM ('DRAFT','CONFIRMED','CANCELLED');
CREATE TABLE "Challan" ("id" TEXT NOT NULL,"challanNumber" TEXT NOT NULL,"customerId" TEXT NOT NULL,"status" "ChallanStatus" NOT NULL DEFAULT 'DRAFT',"totalQuantity" INTEGER NOT NULL,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"confirmedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),CONSTRAINT "Challan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Challan_challanNumber_key" ON "Challan"("challanNumber"); CREATE INDEX "Challan_status_createdAt_id_idx" ON "Challan"("status","createdAt","id");
CREATE TABLE "ChallanItem" ("id" TEXT NOT NULL,"challanId" TEXT NOT NULL,"productId" TEXT,"productNameSnapshot" TEXT NOT NULL,"skuSnapshot" TEXT NOT NULL,"unitPriceSnapshot" DECIMAL(12,2) NOT NULL,"quantity" INTEGER NOT NULL,CONSTRAINT "ChallanItem_pkey" PRIMARY KEY ("id")); CREATE INDEX "ChallanItem_challanId_idx" ON "ChallanItem"("challanId");
ALTER TABLE "Challan" ADD CONSTRAINT "Challan_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Challan" ADD CONSTRAINT "Challan_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ChallanItem" ADD CONSTRAINT "ChallanItem_challanId_fkey" FOREIGN KEY ("challanId") REFERENCES "Challan"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChallanItem" ADD CONSTRAINT "ChallanItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE;
